  const SVG_DMODE = sv(150, `<rect x="90" y="10" width="120" height="130" rx="14" fill="#F2C230" stroke="currentColor"/><rect x="104" y="22" width="92" height="36" rx="4" fill="#C9D6B5"/><text x="150" y="48" text-anchor="middle" font-size="22" font-family="monospace" fill="#1c1c1c">0,58</text>${dsym(150, 82, 0, '#1c1c1c').replace('translate(150 82)', 'translate(150 82) scale(.7)')}<circle cx="150" cy="112" r="16" fill="#333"/><path d="M150 112l10 -10" stroke="#eee" stroke-width="3"/>
    <path d="M90 120C60 120 40 110 30 90" stroke="#E5484D" stroke-width="4" fill="none"/><path d="M210 120C240 120 260 110 270 90" stroke="#333" stroke-width="4" fill="none"/>${tx(6, 80, 'roja → ánodo', 'vizsm')}${tx(294, 80, 'negra → cátodo', 'vizsm', 'end')}${tx(150, 148, 'Modo diodo: la caída (0,5–0,7 V); al revés, «OL»', 'vizsm', 'middle')}`);
  const SVG_SPREAD = sv(150, `<path d="M20 120H285" ${st} stroke-width="1.3"/><path d="M40 120C80 120 100 40 140 40S200 120 250 120" fill="var(--ice)" opacity=".25" stroke="var(--ice)" stroke-width="2"/><path d="M140 40V120" stroke="var(--led)" stroke-width="2" stroke-dasharray="4 3"/><path d="M60 30V120M262 30V120" stroke="var(--err)" stroke-width="2"/>${tx(60, 24, 'min', 'vizlab', 'middle')}${tx(140, 32, 'typ', 'vizlab', 'middle')}${tx(262, 24, 'max', 'vizlab', 'middle')}${tx(150, 138, 'Mil unidades del mismo modelo: casi todas cerca de «typ»,', 'vizsm', 'middle')}${tx(150, 150, 'pero solo min y max están garantizados', 'vizsm', 'middle')}`);
  const plot = (x, title, path, sub) => `<g transform="translate(${x} 0)"><path d="M10 20V120H130" ${st} stroke-width="1.2"/><path d="${path}" fill="none" stroke="var(--led)" stroke-width="2.4"/>${tx(70, 14, title, 'vizlab', 'middle')}${tx(70, 138, sub, 'vizsm', 'middle')}</g>`;
  const SVG_LINLOG = sv(150, plot(10, 'Escala lineal', 'M10 119C70 118 90 112 100 96S112 40 116 22', 'un codo hacia 0,6 V') + plot(155, 'Escala logarítmica', 'M14 112L124 26', 'una recta: ×10 cada 60 mV'));
